    var v = fields.email.value.trim();
    if (!v) return "Email address is required.";
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v)) return "Enter a valid email address, e.g. name@example.com.";
    var taken = getRegistrations().some(function (r) { return norm(r.email) === norm(v); });
    if (taken) return "An account with this email address already exists.";
    return "";
  }

