      username: fields.username.value.trim(),
      email: fields.email.value.trim(),
      dob: fields.dob.value || null,
      registeredAt: new Date().toISOString()
    });

    successMsg.textContent = "Welcome, " + fields.username.value.trim() +
      "! A confirmation will be sent to " + fields.email.value.trim() + ".";
    formView.hidden = true;
    successView.hidden = false;
    successView.setAttribute("tabindex", "-1");
    successView.focus();
  });

  document.getElementById("register-another").addEventListener("click", function () {
    form.reset();
    Object.keys(validators).forEach(function (name) { setError(name, ""); });
    document.querySelectorAll(".toggle-pw").forEach(function (btn) {
      var input = document.getElementById(btn.getAttribute("data-target"));
      input.type = "password";
      btn.textContent = "Show";
      btn.setAttribute("aria-pressed", "false");
    });
    hideBanner();
    successView.hidden = true;
    formView.hidden = false;
    fields.username.focus();
  });
})();
</script>
